from pathlib import Path
changes = {
    'parse.py': '''import json


def parse(text: str):
    try:
        events = json.loads(text)
    except (TypeError, ValueError):
        return []
    return events if isinstance(events, list) else []
''',
    'validate.py': '''def validate(events: list):
    valid = []
    for event in events:
        if not isinstance(event, dict):
            continue
        sku = event.get("sku")
        delta = event.get("delta")
        if isinstance(sku, str) and sku.strip() and isinstance(delta, int) and not isinstance(delta, bool):
            valid.append({"sku": sku, "delta": delta})
    return valid
''',
    'normalize.py': '''def normalize(events: list):
    return [{"sku": event["sku"].strip().casefold(), "delta": event["delta"]} for event in events]
''',
    'aggregate.py': '''def aggregate(events: list):
    balances = {}
    for event in events:
        sku = event["sku"]
        balances[sku] = balances.get(sku, 0) + event["delta"]
    return balances
''',
    'select.py': '''def select(balances: dict):
    return {sku: balance for sku, balance in balances.items() if balance != 0}
''',
    'render.py': '''def render(balances: dict):
    return "\n".join(f"{sku}={balances[sku]}" for sku in sorted(balances))
''',
}
base = Path('src/inventory')
for name, content in changes.items():
    (base / name).write_text(content)
